UITrophyExplosionParticle=function(game,x,y,key,frame){Phaser.Particle.call(this,game,x,y,key,frame);this.kill();};UITrophyExplosionParticle.prototype=Object.create(Phaser.Particle.prototype);UITrophyExplosionParticle.prototype.constructor=UITrophyExplosionParticle;UITrophyExplosionParticle.prototype.onEmit=function(){this.x+=this.body.velocity.x*(Math.random()*3.0+8.0)/15.0;this.y+=this.body.velocity.y*(Math.random()*3.0+15.0)/15.0;};UITrophyExplosionParticle.prototype.update=function(){this.alpha=Math.max(0.0,this.alpha-(0.0094-Math.random()*0.004));this.scale.set(this.scale.x+0.01,this.scale.y+0.01);};UITrophyExplosionParticle.prototype.retire=function(){this.kill();};